// Captured output examples: real paid answers from the weekly catalog buy
// (scripts/catalog-buy.js) that stand in for a tool's published output example
// when its definition carries none.
//
// The file (src/tool-output-examples.json, or TOOL_OUTPUT_EXAMPLES_FILE) is
// generated by scripts/catalog-buy-examples.js and applied through a reviewed
// PR, never by CI. It is keyed by slug: { capturedAt, example, modelBacked }.
//
// MERGE RULE: a hand-written example always wins. A captured example is applied
// only to a tool whose discovery.output.example is absent (or an empty object),
// so this file can never overwrite what a kit author wrote. Where both exist and
// disagree, the examples script reports the mismatch instead.
//
// Every surface that renders a captured example says so: it is a real paid
// answer captured on its date, and for a model-backed tool that it is
// model-generated and varies (captureNote).
import { readFileSync } from "node:fs";

export const DEFAULT_EXAMPLES_FILE = new URL("./tool-output-examples.json", import.meta.url);

/** Trim budget for a published example. Deterministic: same input, same output. */
export const TRIM = Object.freeze({ arrayItems: 3, stringChars: 300, depth: 5 });
const ELLIPSIS = "…";

/**
 * Trim a JSON value for publication: arrays to their first `arrayItems`,
 * strings to `stringChars` plus an ellipsis, and containers past `depth`
 * replaced by an empty container of the same type (so a derived schema keeps
 * the type). Numbers, booleans and null are kept as they are. Top-level keys
 * are never dropped, so the key set stays comparable with the live answer.
 */
export function trimExample(value, opts = {}, depth = 0) {
  const o = { ...TRIM, ...opts };
  if (value === null || typeof value === "number" || typeof value === "boolean") return value;
  if (typeof value === "string") return value.length > o.stringChars ? value.slice(0, o.stringChars) + ELLIPSIS : value;
  if (Array.isArray(value)) {
    if (depth >= o.depth) return [];
    return value.slice(0, o.arrayItems).map((v) => trimExample(v, o, depth + 1));
  }
  if (typeof value === "object") {
    if (depth >= o.depth) return {};
    const out = {};
    for (const [k, v] of Object.entries(value)) if (v !== undefined) out[k] = trimExample(v, o, depth + 1);
    return out;
  }
  return null; // functions, bigint, symbols: never in a JSON answer
}

/** Trim, tightening deterministically until the example fits `maxBytes`. */
export function trimToBudget(value, maxBytes = 6000) {
  const steps = [TRIM, { arrayItems: 2, stringChars: 200, depth: 4 }, { arrayItems: 1, stringChars: 120, depth: 3 }, { arrayItems: 1, stringChars: 60, depth: 2 }];
  let out;
  for (const s of steps) {
    out = trimExample(value, s);
    if (JSON.stringify(out).length <= maxBytes) return { example: out, fits: true };
  }
  return { example: out, fits: false };
}

const isEmptyObject = (v) => v && typeof v === "object" && !Array.isArray(v) && Object.keys(v).length === 0;

/** True when the definition carries an example its author wrote. */
export function hasHandWrittenExample(def) {
  const ex = def?.discovery?.output?.example;
  if (ex === undefined || ex === null || isEmptyObject(ex)) return false;
  return !def.discovery.output.captured;
}

/** Top-level key disagreement between a documented example and a real answer, or null. */
export function keyMismatch(documented, actual) {
  const obj = (v) => v && typeof v === "object" && !Array.isArray(v);
  if (!obj(documented) || !obj(actual) || !Object.keys(documented).length) return null;
  const d = Object.keys(documented), a = Object.keys(actual);
  const missing = d.filter((k) => !a.includes(k));
  const extra = a.filter((k) => !d.includes(k));
  return missing.length || extra.length ? { missing, extra } : null;
}

const DATE_RE = /^\d{4}-\d{2}-\d{2}/;

/** One validated entry, or null. */
export function normalizeEntry(e) {
  if (!e || typeof e !== "object") return null;
  if (typeof e.capturedAt !== "string" || !DATE_RE.test(e.capturedAt)) return null;
  if (e.example === undefined || e.example === null || isEmptyObject(e.example)) return null;
  return { capturedAt: e.capturedAt.slice(0, 10), example: e.example, modelBacked: e.modelBacked === true };
}

/** The captured examples by slug ({} when the file is absent or unreadable). */
export function loadCapturedExamples(file = process.env.TOOL_OUTPUT_EXAMPLES_FILE || DEFAULT_EXAMPLES_FILE) {
  let raw;
  try { raw = JSON.parse(readFileSync(file, "utf8")); } catch { return {}; }
  const out = {};
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return out;
  for (const [slug, e] of Object.entries(raw)) {
    if (slug.startsWith("_")) continue; // a "_note" header
    const n = normalizeEntry(e);
    if (n) out[slug] = n;
  }
  return out;
}

/**
 * Apply captured examples to catalog definitions, in place. Returns the slugs
 * applied and the slugs left alone because a hand-written example exists.
 * A binary tool (its example is a note about bytes) is never given one.
 * `treatAsBare` names slugs whose hand-written example is ignored: a render
 * test needs a tool without one, and every priced tool now has one.
 */
export function applyCapturedExamples(defs, captured, { treatAsBare = [] } = {}) {
  const applied = new Set(), kept = new Set();
  const bare = new Set(treatAsBare);
  for (const def of defs) {
    const entry = def?.slug ? captured[def.slug] : null;
    if (!entry) continue;
    if (hasHandWrittenExample(def) && !bare.has(def.slug)) { kept.add(def.slug); continue; }
    if ((Array.isArray(def.binaryTypes) && def.binaryTypes.length) || (def.mimeType && def.mimeType !== "application/json")) continue;
    // A fresh discovery object: kit definitions can share one by reference.
    def.discovery = {
      ...(def.discovery || {}),
      output: {
        ...(def.discovery?.output || {}),
        example: entry.example,
        captured: { capturedAt: entry.capturedAt, modelBacked: entry.modelBacked || def.modelBacked === true },
      },
    };
    applied.add(def.slug);
  }
  return { applied: [...applied], kept: [...kept] };
}

/** The provenance sentence every surface prints beside a captured example. */
export function captureNote(captured) {
  if (!captured) return "";
  const base = `This example is a real paid answer captured on ${captured.capturedAt}.`;
  return captured.modelBacked ? `${base} The answer is model-generated, so a call with the same input varies.` : base;
}
